"""Tensor-parallel linear layers (Megatron-style) built on torch.distributed.

Weight layout follows torch.nn.Linear: weight has shape (out_features, in_features)
and y = x @ W^T + b.

* ColumnParallelLinear: W is split along the output dimension (the columns of
  W^T / of the logical `x @ W^T` matrix). Each rank computes a slice of the
  output; slices are all-gathered and concatenated along the last dimension.
  Bias is sharded the same way as the output.
* RowParallelLinear: W is split along the input dimension (the rows of W^T).
  Each rank computes a partial output from its slice of the input; partial
  outputs are summed with all-reduce. Bias is kept full on every rank and is
  added once, after the reduction.
"""

import torch
import torch.distributed as dist
import torch.nn as nn
import torch.nn.functional as F


# --------------------------------------------------------------------------- #
# Helpers
# --------------------------------------------------------------------------- #
def _world_size():
    if dist.is_available() and dist.is_initialized():
        return dist.get_world_size()
    return 1


def _rank():
    if dist.is_available() and dist.is_initialized():
        return dist.get_rank()
    return 0


def _divide(numerator, denominator):
    assert numerator % denominator == 0, (
        f"{numerator} is not divisible by world_size {denominator}"
    )
    return numerator // denominator


def _split_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    chunk = _divide(x.size(-1), ws)
    r = _rank()
    return x.narrow(-1, r * chunk, chunk).contiguous()


def _gather_last_dim(x):
    ws = _world_size()
    if ws == 1:
        return x
    x = x.contiguous()
    parts = [torch.empty_like(x) for _ in range(ws)]
    dist.all_gather(parts, x)
    return torch.cat(parts, dim=-1).contiguous()


def _all_reduce(x):
    if _world_size() == 1:
        return x
    x = x.contiguous().clone()
    dist.all_reduce(x, op=dist.ReduceOp.SUM)
    return x


# --------------------------------------------------------------------------- #
# Autograd-aware communication primitives
# --------------------------------------------------------------------------- #
class _CopyToParallelRegion(torch.autograd.Function):
    """Forward: identity. Backward: all-reduce the gradient."""

    @staticmethod
    def forward(ctx, x):
        return x

    @staticmethod
    def backward(ctx, grad):
        return _all_reduce(grad)


class _ReduceFromParallelRegion(torch.autograd.Function):
    """Forward: all-reduce. Backward: identity."""

    @staticmethod
    def forward(ctx, x):
        return _all_reduce(x)

    @staticmethod
    def backward(ctx, grad):
        return grad


class _ScatterToParallelRegion(torch.autograd.Function):
    """Forward: keep this rank's chunk of the last dim. Backward: all-gather."""

    @staticmethod
    def forward(ctx, x):
        return _split_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _gather_last_dim(grad)


class _GatherFromParallelRegion(torch.autograd.Function):
    """Forward: all-gather along last dim. Backward: keep this rank's chunk."""

    @staticmethod
    def forward(ctx, x):
        return _gather_last_dim(x)

    @staticmethod
    def backward(ctx, grad):
        return _split_last_dim(grad)


# --------------------------------------------------------------------------- #
# Layers
# --------------------------------------------------------------------------- #
class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.out_features_per_partition = _divide(out_features, self.world_size)

        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight must have shape {(out_features, in_features)}, "
            f"got {tuple(master_weight.shape)}"
        )

        start = self.rank * self.out_features_per_partition
        end = start + self.out_features_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[start:end, :].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    self.out_features_per_partition,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        x_parallel = _CopyToParallelRegion.apply(x)
        out_parallel = F.linear(x_parallel, self.weight, self.bias)
        return _GatherFromParallelRegion.apply(out_parallel)


class RowParallelLinear(nn.Module):
    def __init__(self, in_features, out_features, bias, master_weight):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.world_size = _world_size()
        self.rank = _rank()
        self.in_features_per_partition = _divide(in_features, self.world_size)

        assert tuple(master_weight.shape) == (out_features, in_features), (
            f"master_weight must have shape {(out_features, in_features)}, "
            f"got {tuple(master_weight.shape)}"
        )

        start = self.rank * self.in_features_per_partition
        end = start + self.in_features_per_partition
        with torch.no_grad():
            shard = master_weight.detach()[:, start:end].clone().contiguous()
        self.weight = nn.Parameter(shard)

        if bias:
            self.bias = nn.Parameter(
                torch.zeros(
                    out_features,
                    dtype=master_weight.dtype,
                    device=master_weight.device,
                )
            )
        else:
            self.register_parameter("bias", None)

    def forward(self, x):
        # Accept either the full input (split it here) or an already-sharded input.
        if x.size(-1) == self.in_features:
            x_parallel = _ScatterToParallelRegion.apply(x)
        elif x.size(-1) == self.in_features_per_partition:
            x_parallel = x
        else:
            raise ValueError(
                f"Input last dim {x.size(-1)} matches neither in_features "
                f"({self.in_features}) nor the per-partition size "
                f"({self.in_features_per_partition})"
            )
        partial = F.linear(x_parallel, self.weight)
        out = _ReduceFromParallelRegion.apply(partial)
        if self.bias is not None:
            out = out + self.bias
        return out
